css:
.smartmoney-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e2ec;
    background: radial-gradient(1200px 600px at 20% -10%, #14283d 0%, #0b1620 55%, #070d14 100%);
    border-radius: 18px;
    border: 1px solid #1b2c3d;
}

.smartmoney-container * {
    box-sizing: border-box;
}

.smartmoney-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0d2236 0%, #103a52 55%, #0e5a52 100%);
    color: #eaf6f4;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.45);
    border: 1px solid #1d3a4f;
}

.smartmoney-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.smartmoney-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #6fe3b0;
    background: rgba(111, 227, 176, 0.10);
    border: 1px solid rgba(111, 227, 176, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.smartmoney-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b6cfdc;
}

.smartmoney-fund {
    display: flex;
    flex-direction: column;
    gap: 8px;
    background: #0f1f2c;
    border: 1px solid #1d3346;
    border-left: 5px solid #2f9bd6;
    border-radius: 12px;
    padding: 12px 18px;
    margin-bottom: 18px;
}

.smartmoney-fund-line {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: space-between;
}

.smartmoney-fund-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #eaf2f8;
}

.smartmoney-fund-meta {
    font-size: 0.82rem;
    color: #8aa3b5;
    line-height: 1.4;
}

.smartmoney-claim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7d96a8;
}

.smartmoney-claim {
    font-weight: 800;
    font-size: 0.9rem;
    color: #f0c45b;
    background: rgba(240, 196, 91, 0.12);
    border: 1px solid rgba(240, 196, 91, 0.32);
    padding: 3px 12px;
    border-radius: 999px;
}

.smartmoney-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9bb3c4;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.smartmoney-period-counter #currentDay,
.smartmoney-period-counter #maxPeriods {
    font-weight: 800;
    color: #6fe3b0;
}

.smartmoney-round-name {
    background: rgba(111, 227, 176, 0.14);
    color: #6fe3b0;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.smartmoney-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f0c45b;
    background: rgba(240, 196, 91, 0.12);
    border: 1px solid rgba(240, 196, 91, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.smartmoney-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.smartmoney-status-card {
    background: linear-gradient(180deg, #11212f 0%, #0d1a25 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
    border: 1px solid #1c3142;
    border-top: 4px solid #2f9bd6;
}

.smartmoney-card-alpha { border-top-color: #6fe3b0; }
.smartmoney-card-te { border-top-color: #f0c45b; }
.smartmoney-card-aum { border-top-color: #2f9bd6; }
.smartmoney-card-esg { border-top-color: #8f7be0; }

.smartmoney-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #82a0b3;
}

.smartmoney-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eef5fa;
    font-variant-numeric: tabular-nums;
}

.smartmoney-card-alpha .smartmoney-value { color: #ff6b6b; }
.smartmoney-card-alpha.smartmoney-alpha-pos .smartmoney-value { color: #4fd99b; }
.smartmoney-card-te .smartmoney-value { color: #f0c45b; }
.smartmoney-card-te.smartmoney-te-hot .smartmoney-value { color: #ff8a4c; }
.smartmoney-card-aum .smartmoney-value { color: #4db5ec; }
.smartmoney-card-esg .smartmoney-value { color: #b39cff; }
.smartmoney-card-esg.smartmoney-esg-bad .smartmoney-value { color: #ff6b6b; }
.smartmoney-card-esg.smartmoney-esg-good .smartmoney-value { color: #4fd99b; }

.smartmoney-sublabel {
    font-size: 0.74rem;
    color: #7d96a8;
    line-height: 1.35;
}

.smartmoney-mandate-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f1f2c;
    border: 1px solid #1d3346;
    color: #9bb3c4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.smartmoney-mandate-bar #mandateDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff6b6b;
    font-weight: 800;
}

.smartmoney-mandate-bar.smartmoney-mandate-safe #mandateDisplay { color: #4fd99b; }
.smartmoney-mandate-bar.smartmoney-mandate-mid #mandateDisplay { color: #f0c45b; }

.smartmoney-briefing {
    display: flex;
    gap: 14px;
    background: #0f1f2c;
    border: 1px solid #1d3346;
    border-left: 5px solid #6fe3b0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
}

.smartmoney-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.smartmoney-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf2f8;
    margin-bottom: 6px;
}

.smartmoney-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #bcd1de;
}

.smartmoney-briefing-text strong { color: #6fe3b0; }
.smartmoney-briefing-text em { color: #f0c45b; font-style: italic; }

.smartmoney-controls {
    background: linear-gradient(180deg, #0f2030 0%, #0c1822 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
    border: 1px solid #1c3142;
}

.smartmoney-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf2f8;
    border-bottom: 2px solid #1c3142;
    padding-bottom: 8px;
}

.smartmoney-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c4d6e2;
    margin: 14px 0 6px;
}

.smartmoney-container select,
.smartmoney-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #294258;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1a26;
    color: #e6eef4;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.smartmoney-container select:focus,
.smartmoney-container input[type="number"]:focus {
    outline: none;
    border-color: #6fe3b0;
    box-shadow: 0 0 0 3px rgba(111, 227, 176, 0.18);
}

.smartmoney-container select option {
    background-color: #0c1a26;
    color: #e6eeff;
}

.smartmoney-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6fe3b0;
}

.smartmoney-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9bb3c4;
    margin-top: 4px;
}

.smartmoney-range-readout span:nth-child(2) {
    color: #f0c45b;
    font-weight: 800;
}

.smartmoney-hint {
    font-size: 0.8rem;
    color: #7d96a8;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.smartmoney-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.smartmoney-container .btn-primary {
    background: linear-gradient(135deg, #0e5a52 0%, #14a07f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(20, 160, 127, 0.32);
}

.smartmoney-container .btn-primary:hover {
    filter: brightness(1.1);
}

.smartmoney-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #294258;
    color: #9bb3c4;
    background: transparent;
}

.smartmoney-coach {
    background: linear-gradient(160deg, #122a1f 0%, #0e2030 100%);
    color: #d7ece3;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
    border: 1px solid #1f4034;
}

.smartmoney-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6fe3b0;
    margin-bottom: 8px;
}

.smartmoney-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.smartmoney-coach-body strong { color: #8ff0c5; }
.smartmoney-coach-body em { color: #f0c45b; font-style: italic; }

.smartmoney-history,
.smartmoney-chart {
    background: linear-gradient(180deg, #0f2030 0%, #0c1822 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
    border: 1px solid #1c3142;
}

.smartmoney-history h3,
.smartmoney-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf2f8;
}

.smartmoney-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #bcd1de;
}

.smartmoney-container table#usfHistoryTable th {
    background: #0e2434;
    color: #6fe3b0;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1c3142;
}

.smartmoney-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #16273500;
    border-bottom: 1px solid #142532;
    color: #bcd1de;
}

.smartmoney-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0e1c28;
}

.smartmoney-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .smartmoney-container {
        padding: 14px;
    }
    .smartmoney-header h1 {
        font-size: 1.7rem;
    }
    .smartmoney-fund-line {
        flex-direction: column;
        gap: 4px;
    }
    .smartmoney-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .smartmoney-value {
        font-size: 2rem;
    }
    .smartmoney-clock {
        margin-left: 0;
    }
    .smartmoney-period-counter {
        font-size: 0.88rem;
    }
    .smartmoney-mandate-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .smartmoney-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / client-debrief scorecard (append-only, namespaced) ===== */
.sm-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.sm-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8194; margin-bottom: 6px; }
.sm-cm-verdict { font-size: 22px; font-weight: 700; color: #1c2333; margin-bottom: 8px; }
.sm-cm-score { font-size: 16px; color: #1c2333; margin-bottom: 16px; }
.sm-cm-score strong { color: #1f7a5a; }
.sm-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8194; margin-bottom: 8px; }
.sm-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.sm-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.sm-cm-target.sm-cm-met { background: #e6f5ee; color: #176046; border-color: #b6e0cc; }
.sm-cm-target.sm-cm-missed { background: #fdecea; color: #99332b; border-color: #f2c8c3; }
.sm-cm-tick { font-weight: 700; }
.sm-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.sm-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: #f3f5f9; border-radius: 8px; min-width: 96px; }
.sm-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8194; }
.sm-cm-metric strong { font-size: 16px; color: #1c2333; }
.sm-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.sm-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: #eef6f2; border-left: 3px solid #1f7a5a; border-radius: 4px; color: #26303f; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .sm-cm-metric { min-width: 72px; } .sm-cm-verdict { font-size: 19px; } }

