(function() {
    'use strict';

    class SmartMoneyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Smart or Ethical Money`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Meridiaan European Equity Fund).
            this.START_ALPHA = -60;     // net alpha vs MSCI Europe (bps annualized)
            this.GROSS_ALPHA = 25;      // approx gross alpha (bps)
            this.START_FEE = 0.85;      // management fee (%)
            this.PASSIVE_FEE = 0.20;    // index-plus-ESG rival fee (%)
            this.START_TE = 2.1;        // tracking error (%)
            this.START_AUM = 2400;      // fund AUM (€M)
            this.START_ESG = 48;        // ESG integrity index (0-100)
            this.MANDATE = 640;         // €640M pension mandate
            this.INFLOW = 250;          // strong-performance inflow (€M)
            this.REDEMPTION = 200;      // lagging redemption (€M)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    alpha: this.START_ALPHA,        // net alpha vs benchmark (bps)
                    grossAlpha: this.GROSS_ALPHA,   // gross alpha (bps)
                    fee: this.START_FEE,            // current fee (%)
                    te: this.START_TE,              // tracking error (%)
                    aum: this.START_AUM,            // fund AUM (€M)
                    esg: this.START_ESG,            // ESG integrity index (0-100)
                    mandate: 35,                    // confidence the €640M stays (0-100)
                    claim: `light`,                 // SFDR claim currently on the factsheet
                    screen: `light`,                // SRI screen actually applied
                    greenwashing: false,            // claim > holdings -> AFM exposure
                    persistenceTrap: false,         // chased reversing winners
                    concentrationTrap: false,       // Article 9 with no risk budget
                    feeTrap: false,                 // never addressed the fee
                    flowsTrap: false,               // managed the book in a vacuum
                    ideologyTrap: false,            // answered with belief not evidence
                    diagnosedWell: false,           // R1 named the fee + weak persistence
                    alphaHistory: [this.START_ALPHA],
                    teHistory: [this.START_TE],
                    aumHistory: [this.START_AUM],
                    esgHistory: [this.START_ESG],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the concept's classic errors — a
                // blind click-through must NOT auto-win.
                state.decisions = {
                    driver: `selection`,
                    persist: `strong`,
                    skill: `skill`,
                    screen: `article9`,
                    claim: `overclaim`,
                    event: `soften`,
                    persistWt: 60,
                    risk: `high`,
                    fee: `hold`,
                    flows: `ignore`,
                    verdict: `ideology_pro`,
                    future: `closet`,
                    defend: `cherrypick`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dr = document.getElementById(`driverInput`);
                const pe = document.getElementById(`persistInput`);
                const sk = document.getElementById(`skillInput`);
                if (dr) decisions.driver = dr.value;
                if (pe) decisions.persist = pe.value;
                if (sk) decisions.skill = sk.value;
                if (!decisions.driver || !decisions.persist || !decisions.skill) { warn(`warn_missing`); return false; }
            } else if (round === 2) {
                const sc = document.getElementById(`screenInput`);
                const cl = document.getElementById(`claimInput`);
                const ev = document.getElementById(`eventInput`);
                if (sc) decisions.screen = sc.value;
                if (cl) decisions.claim = cl.value;
                if (ev) decisions.event = ev.value;
                if (!decisions.screen || !decisions.claim || !decisions.event) { warn(`warn_missing`); return false; }
            } else if (round === 3) {
                const pw = document.getElementById(`persistWtInput`);
                const ri = document.getElementById(`riskInput`);
                const fe = document.getElementById(`feeInput`);
                const fl = document.getElementById(`flowsInput`);
                if (pw) decisions.persistWt = parseInt(pw.value, 10);
                if (ri) decisions.risk = ri.value;
                if (fe) decisions.fee = fe.value;
                if (fl) decisions.flows = fl.value;
                if (!Number.isFinite(decisions.persistWt) || decisions.persistWt < 0 || decisions.persistWt > 100) {
                    warn(`warn_persistwt_range`); return false;
                }
            } else if (round === 4) {
                const ve = document.getElementById(`verdictInput`);
                const fu = document.getElementById(`futureInput`);
                const de = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ve) decisions.verdict = ve.value;
                if (fu) decisions.future = fu.value;
                if (de) decisions.defend = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alphaDelta = 0, teDelta = 0, esgDelta = 0, mandateDelta = 0;
            let flowDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the gap (Common Errors: blaming selection, mis-reading persistence/skill).
                switch (d.driver) {
                    case `fee`: mandateDelta += 6; ds.diagnosedWell = true; coachKey = `coach_r1_fee`; break;
                    case `selection`: mandateDelta -= 2; coachKey = `coach_r1_selection`; break;
                    case `luck`: mandateDelta -= 4; coachKey = `coach_r1_luck`; break;
                    case `screen`: mandateDelta -= 5; esgDelta -= 4; coachKey = `coach_r1_screen`; break;
                }

                switch (d.persist) {
                    case `weak`: mandateDelta += 5; alphaDelta += 2; break;
                    case `strong`: mandateDelta -= 5; coachKey = `coach_r1_persiststrong`; break;
                    case `ignore`: mandateDelta -= 1; coachKey = `coach_r1_persistignore`; break;
                }

                switch (d.skill) {
                    case `test`: mandateDelta += 5; break;
                    case `skill`: mandateDelta -= 3; coachKey = `coach_r1_skillskill`; break;
                    case `luck`: mandateDelta -= 2; coachKey = `coach_r1_skillluck`; break;
                }

                if (d.driver === `fee` && d.persist === `weak` && d.skill === `test`) {
                    ds.diagnosedWell = true; coachKey = `coach_r1_sharp`; summaryKey = `sum_r1_good`;
                } else {
                    summaryKey = `sum_r1_weak`;
                }
            } else if (round === 2) {
                // Choose the SRI screen and — critically — match the claim to holdings.
                ds.screen = d.screen;
                switch (d.screen) {
                    case `light`:
                        esgDelta += 4;
                        coachKey = `coach_r2_light`;
                        break;
                    case `floor`:
                        teDelta += 0.6; esgDelta += 16; alphaDelta += 2;
                        break;
                    case `bestinclass`:
                        // ter Horst: responsible screening need not destroy risk-adjusted return.
                        teDelta += 0.9; esgDelta += 24; alphaDelta += 4;
                        coachKey = `coach_r2_bestinclass`;
                        break;
                    case `article9`:
                        // Excludes ~22% of benchmark — TE jumps toward 4.0-4.8%, concentrated.
                        teDelta += 2.4; esgDelta += 30;
                        coachKey = `coach_r2_article9`;
                        break;
                }

                // The SFDR claim is a COMPLIANCE decision (greenwashing is contagious).
                const greenScreen = (d.screen === `article9` || d.screen === `bestinclass`);
                switch (d.claim) {
                    case `match`:
                        esgDelta += 14; mandateDelta += 6;
                        ds.greenwashing = false;
                        ds.claim = (d.screen === `article9`) ? `article9` : (greenScreen ? `art8plus` : d.screen);
                        break;
                    case `overclaim`:
                        // Marketing greener than holdings support -> AFM inquiry, firm-wide outflows.
                        ds.claim = `article9`;
                        if (!greenScreen) {
                            ds.greenwashing = true;
                            esgDelta -= 34; mandateDelta -= 16; flowDelta -= 150;
                            coachKey = `coach_r2_greenwash`;
                        } else if (d.screen === `bestinclass`) {
                            ds.greenwashing = true;
                            esgDelta -= 18; mandateDelta -= 8; flowDelta -= 80;
                            coachKey = `coach_r2_overclaim`;
                        } else {
                            esgDelta += 6;
                        }
                        break;
                    case `under`:
                        ds.claim = (d.screen === `article9`) ? `art8plus` : d.screen;
                        esgDelta -= 4; mandateDelta -= 2;
                        if (greenScreen && coachKey === `coach_default`) coachKey = `coach_r2_under`;
                        break;
                }

                // The excluded-energy-stock +18% event tests screen discipline.
                switch (d.event) {
                    case `hold`: mandateDelta += 4; esgDelta += 4; break;
                    case `soften`: esgDelta -= 10; mandateDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_soften`; break;
                    case `panic`: esgDelta -= 22; mandateDelta -= 8; ds.greenwashing = ds.greenwashing || (d.claim !== `under`); if (coachKey === `coach_default` || coachKey === `coach_r2_article9`) coachKey = `coach_r2_panic`; break;
                }

                if (d.claim === `match` && (d.screen === `bestinclass` || d.screen === `floor`) && d.event === `hold`) {
                    summaryKey = `sum_r2_good`;
                } else if (ds.greenwashing) {
                    summaryKey = `sum_r2_greenwash`;
                } else if (d.screen === `article9` && d.claim === `match`) {
                    summaryKey = `sum_r2_article9`;
                } else {
                    summaryKey = `sum_r2_weak`;
                }
            } else if (round === 3) {
                // Construct: persistence vs fundamentals, active-risk budget, fee, flows.
                const pw = d.persistWt / 100;

                // Performance-persistence tilt: feels smart, reverses after costs (ter Horst).
                if (pw >= 0.5) {
                    ds.persistenceTrap = true;
                    // The harder you chase trailing winners, the worse net alpha after costs.
                    alphaDelta -= Math.round((pw - 0.25) * 70);   // up to ~ -53 bps at 100%
                    teDelta += pw * 1.6;
                    coachKey = `coach_r3_persist`;
                } else {
                    // Valuation/quality tilt with light persistence -> modest, durable alpha.
                    alphaDelta += Math.round((0.5 - pw) * 36);    // up to +18 bps near 0%
                    teDelta += pw * 0.4;
                }

                // Active-risk budget.
                switch (d.risk) {
                    case `mid`: alphaDelta += 6; mandateDelta += 4; break;
                    case `low`: alphaDelta += 1; teDelta -= 0.4; break;
                    case `high`:
                        teDelta += 1.6; mandateDelta -= 4;
                        if (ds.screen === `article9`) { ds.concentrationTrap = true; alphaDelta -= 20; coachKey = `coach_r3_concentration`; }
                        else { alphaDelta -= 8; if (coachKey === `coach_default`) coachKey = `coach_r3_risk`; }
                        break;
                }

                // The fee is a first-order strategic variable (net-of-fee dominates).
                switch (d.fee) {
                    case `cut`:
                        // Cutting toward 0.55% lifts NET alpha by ~30 bps and reassures the client.
                        ds.fee = 0.55; alphaDelta += 30; mandateDelta += 12;
                        break;
                    case `hold`:
                        ds.feeTrap = true; mandateDelta -= 6;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_fee`;
                        break;
                    case `raise`:
                        ds.fee = 1.00; ds.feeTrap = true; alphaDelta -= 15; mandateDelta -= 14;
                        coachKey = `coach_r3_feeraise`;
                        break;
                }

                // Flows event (cost feedback loop). Sign depends on relative performance so far.
                const performingWell = ds.alpha + alphaDelta > -20;
                if (performingWell) {
                    flowDelta += this.INFLOW;     // strong relative performance attracts inflows
                    if (d.flows === `liquid`) { flowDelta += 40; mandateDelta += 3; }
                } else {
                    // Lagging -> redemption forces selling.
                    if (d.flows === `liquid`) {
                        flowDelta -= this.REDEMPTION; mandateDelta += 4;   // sleeve absorbs the shock
                    } else if (d.flows === `firesale`) {
                        ds.flowsTrap = true; flowDelta -= (this.REDEMPTION + 60); alphaDelta -= 12; mandateDelta -= 6;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_firesale`;
                    } else { // ignore
                        ds.flowsTrap = true; flowDelta -= (this.REDEMPTION + 30); alphaDelta -= 8; mandateDelta -= 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_flows`;
                    }
                }
                if (d.flows === `ignore`) ds.flowsTrap = true;

                if (pw <= 0.25 && d.risk === `mid` && d.fee === `cut` && d.flows === `liquid`) {
                    coachKey = `coach_r3_strong`; summaryKey = `sum_r3_good`;
                } else if (ds.persistenceTrap && d.fee !== `cut`) {
                    summaryKey = `sum_r3_persist`;
                } else if (ds.concentrationTrap) {
                    summaryKey = `sum_r3_concentration`;
                } else if (ds.feeTrap) {
                    summaryKey = `sum_r3_fee`;
                } else {
                    summaryKey = `sum_r3_weak`;
                }
            } else if (round === 4) {
                // Recover & defend: evidence vs ideology, future of the mandate.
                switch (d.verdict) {
                    case `evidence`: mandateDelta += 10; alphaDelta += 4; coachKey = `coach_r4_evidence`; break;
                    case `ideology_pro`: ds.ideologyTrap = true; mandateDelta -= 6; coachKey = `coach_r4_ideologypro`; break;
                    case `ideology_con`: ds.ideologyTrap = true; mandateDelta -= 8; esgDelta -= 6; coachKey = `coach_r4_ideologycon`; break;
                }

                switch (d.future) {
                    case `active_evidence`:
                        // Defensible only if the numbers actually support it.
                        if (ds.alpha + alphaDelta >= -10 && !ds.greenwashing) { mandateDelta += 10; alphaDelta += 2; }
                        else { mandateDelta -= 4; }
                        break;
                    case `passive`:
                        // An honest concession if the edge truly died; neutral-to-mild.
                        if (ds.alpha + alphaDelta < -30 || ds.feeTrap) { mandateDelta += 4; }
                        else { mandateDelta -= 6; coachKey = `coach_r4_passive`; }
                        break;
                    case `closet`:
                        // Full fee, benchmark-hugging — the worst of both worlds.
                        ds.feeTrap = true; mandateDelta -= 12; alphaDelta -= 6; coachKey = `coach_r4_closet`;
                        break;
                }

                switch (d.defend) {
                    case `attribution`: mandateDelta += 8; if (d.verdict === `evidence`) coachKey = `coach_r4_attribution`; break;
                    case `cherrypick`: mandateDelta -= 6; coachKey = `coach_r4_cherrypick`; break;
                    case `blame`: mandateDelta -= 9; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { mandateDelta += 4; }
                else if (d.conviction <= 25) { mandateDelta -= 3; }

                if (d.verdict === `evidence` && d.future === `active_evidence` && d.defend === `attribution`) {
                    summaryKey = `sum_r4_good`;
                } else {
                    summaryKey = `sum_r4_weak`;
                }
            }

            // ---- Apply deltas (clamped). ----
            ds.alpha = Math.round(ds.alpha + alphaDelta);
            ds.te = Math.max(0.5, Math.round((ds.te + teDelta) * 100) / 100);
            ds.esg = Math.max(0, Math.min(100, Math.round(ds.esg + esgDelta)));
            ds.aum = Math.max(0, Math.round(ds.aum + flowDelta));

            // Mandate confidence is also pulled by the realized numbers it cares about:
            // positive net alpha, a defensible (not runaway) tracking error, and a
            // clean ESG claim. This couples the KPIs to the 90-day-cliff outcome.
            let realityPull = 0;
            if (ds.alpha >= 0) realityPull += 8; else if (ds.alpha <= -50) realityPull -= 6;
            if (ds.te > 4.5) realityPull -= 6; else if (ds.te <= 3.2) realityPull += 3;
            if (ds.esg >= 70) realityPull += 4; else if (ds.esg < 35) realityPull -= 5;
            if (ds.greenwashing) realityPull -= 6;
            ds.mandate = Math.max(0, Math.min(100, Math.round(ds.mandate + mandateDelta + realityPull)));

            ds.alphaHistory.push(ds.alpha);
            ds.teHistory.push(ds.te);
            ds.aumHistory.push(ds.aum);
            ds.esgHistory.push(ds.esg);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;
            const claimEl = document.getElementById(`claimDisplay`);
            if (claimEl) claimEl.textContent = this._claimLabel(ds.claim);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            // (domainState.performance.overallScore, then domainState.score). Same _composite()
            // formula as the completion scorecard, so per-round score == final composite.
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                alpha: ds.alpha,
                alphaDelta: Math.round(alphaDelta),
                te: ds.te,
                aum: ds.aum,
                flowDelta: Math.round(flowDelta),
                esg: ds.esg,
                mandate: ds.mandate,
                fee: ds.fee,
                greenwashing: ds.greenwashing,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _claimLabel(code) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (code === `article9`) return t(`claim_art9`);
            if (code === `art8plus`) return t(`claim_art8plus`);
            if (code === `bestinclass`) return t(`claim_art8plus`);
            if (code === `floor`) return t(`claim_art8plus`);
            return t(`claim_art8`);
        }

        _mandateLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 65) return t(`mandate_secure`);
            if (v >= 40) return t(`mandate_fragile`);
            return t(`mandate_atrisk`);
        }

        _fmtAlpha(v) {
            const n = Math.round(Number(v));
            const sign = n > 0 ? `+` : (n < 0 ? `−` : `±`);
            return `${sign}${Math.abs(n)} bps`;
        }

        _fmtTe(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 100) / 100).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `%`;
        }

        _fmtAum(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v));
            const grouped = n.toLocaleString(lang === `es` ? `es-ES` : `en-US`);
            return `€${grouped}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`alphaDisplay`, `domainState.alpha`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.smartmoney-card-alpha`);
                if (card) card.classList.toggle(`smartmoney-alpha-pos`, n >= 0);
                return self._fmtAlpha(n);
            });

            uiManager.bind(`teDisplay`, `domainState.te`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.smartmoney-card-te`);
                if (card) card.classList.toggle(`smartmoney-te-hot`, n > 4.0);
                return self._fmtTe(n);
            });

            uiManager.bind(`aumDisplay`, `domainState.aum`, (v) => self._fmtAum(v));

            uiManager.bind(`esgDisplay`, `domainState.esg`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.smartmoney-card-esg`);
                if (card) {
                    card.classList.toggle(`smartmoney-esg-bad`, n < 35);
                    card.classList.toggle(`smartmoney-esg-good`, n >= 70);
                }
                return `${n}`;
            });

            uiManager.bind(`mandateDisplay`, `domainState.mandate`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.smartmoney-mandate-bar`);
                if (bar) {
                    bar.classList.toggle(`smartmoney-mandate-safe`, n >= 65);
                    bar.classList.toggle(`smartmoney-mandate-mid`, n >= 40 && n < 65);
                }
                return self._mandateLabel(n);
            });

            uiManager.bind(`claimDisplay`, `domainState.claim`, (v) => self._claimLabel(String(v)));

            // Persistence-weight slider readout.
            const pw = document.getElementById(`persistWtInput`);
            const pwReadout = document.getElementById(`persistWtReadout`);
            if (pw && pwReadout) {
                pwReadout.textContent = pw.value;
                pw.addEventListener(`input`, function() { pwReadout.textContent = pw.value; });
            }
        }

        getChartConfig() {
            return {
                alphaChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Net alpha vs MSCI Europe (bps)`,
                                data: [],
                                borderColor: `#4fd99b`,
                                backgroundColor: `rgba(79,217,155,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#4fd99b`,
                                yAxisID: `y`
                            },
                            {
                                label: `Tracking error (% ×10)`,
                                data: [],
                                borderColor: `#f0c45b`,
                                backgroundColor: `rgba(240,196,91,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#f0c45b`,
                                yAxisID: `y`
                            },
                            {
                                label: `ESG integrity (0–100)`,
                                data: [],
                                borderColor: `#b39cff`,
                                backgroundColor: `rgba(179,156,255,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b39cff`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9bb3c4`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                position: `left`,
                                suggestedMin: -80, suggestedMax: 100,
                                ticks: { color: `#82a0b3` },
                                grid: { color: `rgba(155,179,196,0.10)` },
                                title: { display: true, text: `bps · TE×10 · ESG`, color: `#82a0b3` }
                            },
                            x: {
                                ticks: { color: `#82a0b3` },
                                grid: { color: `rgba(155,179,196,0.06)` },
                                title: { display: true, text: `Round`, color: `#82a0b3` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.alphaHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Tracking error is 0.5–5% — scale ×10 to share the axis legibly.
            const teScaled = ds.teHistory.map((v) => Math.round(v * 10));
            return {
                alphaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.alphaHistory.map((v) => Math.round(v)) },
                        { data: teScaled },
                        { data: ds.esgHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.34/0.22/0.18/0.26 sum to 1),
            // extracted so calculateResults (per round) and getPerformanceSummary produce one number.
            const alpha = Math.round(ds.alpha);
            const te = Math.round(ds.te * 100) / 100;
            const esg = Math.round(ds.esg);
            const mandate = Math.round(ds.mandate);
            const alphaScore = Math.max(0, Math.min(100, (alpha + 80) / 1.4));
            const teScore = Math.max(0, Math.min(100, (5.0 - te) / 3.5 * 100));
            return Math.round(alphaScore * 0.34 + esg * 0.22 + teScore * 0.18 + mandate * 0.26);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized client/board debrief scorecard (was: framework default that
            // discarded score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite
                : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];

            const chip = function (ok, label) {
                return '<div class="sm-cm-target ' + (ok ? 'sm-cm-met' : 'sm-cm-missed') + '">'
                    + '<span class="sm-cm-tick">' + (ok ? '✓' : '✗') + '</span>'
                    + '<span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.positiveAlpha, t('tgt_alpha'))
                + chip(!!summary.cleanEsg, t('tgt_esg'))
                + chip(!!summary.disciplinedRisk, t('tgt_te'))
                + chip(!!summary.mandateKept, t('tgt_mandate'))
                + chip(!!summary.grewBook, t('tgt_aum'));

            const metric = function (label, val) {
                return '<div class="sm-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const alphaStr = (typeof this._fmtAlpha === 'function' && summary.alpha != null) ? this._fmtAlpha(summary.alpha) : (summary.alpha != null ? summary.alpha + ' bps' : '-');
            const aumStr = (typeof this._fmtAum === 'function' && summary.aum != null) ? this._fmtAum(summary.aum) : (summary.aum != null ? '€' + summary.aum + 'M' : '-');
            const teStr = (summary.te != null) ? (summary.te + '%') : '-';
            const metrics = ''
                + metric(t('kpi_alpha'), alphaStr)
                + metric(t('kpi_te'), teStr)
                + metric(t('kpi_aum'), aumStr)
                + metric(t('kpi_esg'), (summary.esg != null ? summary.esg : '-') + '/100')
                + metric(t('kpi_mandate'), (summary.mandate != null ? summary.mandate : '-') + '/100');

            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');

            return ''
                + '<div class="sm-cm">'
                +   '<div class="sm-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="sm-cm-verdict">' + verdict + '</div>'
                +   '<div class="sm-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="sm-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="sm-cm-targets">' + targets + '</div>'
                +   '<div class="sm-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="sm-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const alpha = Math.round(ds.alpha);
            const te = Math.round(ds.te * 100) / 100;
            const aum = Math.round(ds.aum);
            const esg = Math.round(ds.esg);
            const mandate = Math.round(ds.mandate);

            const positiveAlpha = alpha >= 0;
            const disciplinedRisk = te <= 4.0;
            const cleanEsg = esg >= 60 && !ds.greenwashing;
            const grewBook = aum >= this.START_AUM;
            const mandateKept = mandate >= 55;

            // Composite balances the four things the board/client judge.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.greenwashing) pattern = `greenwash`;
            else if (ds.persistenceTrap && alpha < -30) pattern = `persistence`;
            else if (ds.concentrationTrap) pattern = `concentration`;
            else if (ds.feeTrap && alpha < 0) pattern = `fee`;
            else if (ds.ideologyTrap) pattern = `ideology`;
            else if (positiveAlpha && cleanEsg && disciplinedRisk) pattern = `smart_and_ethical`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (mandateKept && positiveAlpha && cleanEsg && disciplinedRisk && composite >= 72) perfKey = `grade_smart_ethical`;
            else if (positiveAlpha && cleanEsg && composite >= 60) perfKey = `grade_defensible`;
            else if (ds.greenwashing) perfKey = `grade_greenwash`;
            else if (ds.persistenceTrap && alpha < -30) perfKey = `grade_persistence`;
            else if (ds.concentrationTrap) perfKey = `grade_concentration`;
            else if (mandate >= 40) perfKey = `grade_notice`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `smart_and_ethical`) insights.push(window.mySimulation.t(`insight_smart`));
            else if (pattern === `greenwash`) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (pattern === `persistence`) insights.push(window.mySimulation.t(`insight_persistence`));
            else if (pattern === `concentration`) insights.push(window.mySimulation.t(`insight_concentration`));
            else if (pattern === `fee`) insights.push(window.mySimulation.t(`insight_fee`));
            else if (pattern === `ideology`) insights.push(window.mySimulation.t(`insight_ideology`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.flowsTrap) insights.push(window.mySimulation.t(`insight_flows`));
            if (ds.feeTrap && pattern !== `fee`) insights.push(window.mySimulation.t(`insight_fee_drag`));
            if (te > 4.5) insights.push(window.mySimulation.t(`insight_te_high`));
            if (positiveAlpha && !cleanEsg) insights.push(window.mySimulation.t(`insight_alpha_no_esg`));
            if (cleanEsg && !positiveAlpha) insights.push(window.mySimulation.t(`insight_esg_no_alpha`));

            return {
                gradeKey: perfKey,
                score: composite,
                alpha: alpha,
                te: te,
                aum: aum,
                esg: esg,
                mandate: mandate,
                positiveAlpha: positiveAlpha,
                disciplinedRisk: disciplinedRisk,
                cleanEsg: cleanEsg,
                grewBook: grewBook,
                mandateKept: mandateKept,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashing) return window.mySimulation.t(`hint_greenwash`);
            if (ds.concentrationTrap) return window.mySimulation.t(`hint_concentration`);
            if (ds.persistenceTrap && ds.alpha < -40) return window.mySimulation.t(`hint_persistence`);
            if (ds.feeTrap && ds.alpha < 0 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_fee`);
            if (ds.flowsTrap) return window.mySimulation.t(`hint_flows`);
            if (ds.alpha >= 0 && ds.esg >= 60 && ds.te <= 4.0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.alpha`, label: `Net alpha`, i18nKey: `col_alpha`, formatter: (v) => self._fmtAlpha(v) },
                { key: `results.te`, label: `TE`, i18nKey: `col_te`, formatter: (v) => self._fmtTe(Number(v)) },
                { key: `results.aum`, label: `AUM`, i18nKey: `col_aum`, formatter: (v) => self._fmtAum(v) },
                { key: `results.esg`, label: `ESG`, i18nKey: `col_esg`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

